function renderModule() { const market = $("market-content"), capital = $("capital-content"), vcp = $("vcp-content"), signals=$("signals-content"), backtest=$("backtest-content"), placeholder = $("module-placeholder"), date = $("date-control"); market.classList.add("hidden");capital.classList.add("hidden");vcp.classList.add("hidden");signals.classList.add("hidden");backtest.classList.add("hidden"); placeholder.classList.add("hidden"); date.classList.add("hidden"); if (activeModule === "market") { market.classList.remove("hidden"); date.classList.remove("hidden"); return; } if (activeModule === "capital") { capital.classList.remove("hidden"); date.classList.remove("hidden"); loadCapital($("date-select").value); return; } if (activeModule === "vcp") { vcp.classList.remove("hidden"); date.classList.remove("hidden"); loadVcp($("date-select").value); return; } if(activeModule==="signals"){signals.classList.remove("hidden");date.classList.remove("hidden");loadSignals($("date-select").value);return;} if(activeModule==="backtest"){backtest.classList.remove("hidden");date.classList.remove("hidden");loadBacktest($("date-select").value);return;} placeholder.innerHTML = `<p class="section-label">${MODULES[activeModule]}</p><h2>模块尚未发布展示数据</h2><p>后续该模块将通过 <code>dashboard/data/</code> 发布独立数据包，由本面板只读展示。</p>`; placeholder.classList.remove("hidden"); }

