  const simpleTable=(title,rows)=>`<section class="capital-threshold-group"><h3>${title}</h3><div class="table-scroll"><table class="capital-threshold-table"><thead><tr><th>指标</th><th>标准</th><th>实际含义</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.metric)}</td><td>${esc(row.standard)}</td><td>${esc(row.meaning)}</td></tr>`).join("")||"<tr><td colspan='3' class='muted'>当日数据包未发布阈值说明</td></tr>"}</tbody></table></div></section>`;
  const stateTable=(scope,rows)=>`<article class="capital-state-rule-card"><h5>${esc(scope)}</h5><div class="table-scroll"><table class="capital-threshold-table capital-state-rule-table"><thead><tr><th>状态</th><th>判定标准</th><th>实际含义</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${capitalThresholdState(row.state)}</td><td>${esc(row.standard)}</td><td>${esc(row.meaning)}</td></tr>`).join("")||"<tr><td colspan='3' class='muted'>暂无规则</td></tr>"}</tbody></table></div></article>`;
  const stateRules=rules.state_rules||[];
