function loadVcpContext(date) { const contexts=window.QUANT_DASHBOARD_VCP_CONTEXTS||{}; if(contexts[date])return Promise.resolve(contexts[date]); return new Promise((resolve,reject)=>{const script=document.createElement("script");script.src=`data/${monthPath(date)}/vcp_context_${date}.js`;script.onload=()=>{const value=(window.QUANT_DASHBOARD_VCP_CONTEXTS||{})[date];script.remove();resolve(value);};script.onerror=()=>reject(new Error(`未找到 ${date} 的 Bloom VCP 数据，请先生成 Bloom 输出和面板数据包。`));document.head.appendChild(script);}); }
