  if(row.setup_signal==="PULLBACK_BUY") return `关注 ${esc(plan.anchor||"均线/支撑位")} 附近回踩；参考支撑 ${price(plan.support_price)}，失效 ${price(plan.invalid_price)}；低量确认阈值 ${volume(plan.ideal_volume_max)}。`;
